182	/**
183	 * Default configuration for individual account type
184	 * Extends the base config with individual-specific settings
185	 * @type {Object}
186	 */
187	const defaultIndividualConfig = {
188	  ...defaultConfig,
189	  business: {
190	    ...defaultConfig.business,
191	    name: 'Serviço Individual',
192	    type: 'Profissional Autônomo',
193	  },
194	  database: {
195	    ...defaultConfig.database,
196	    dynamodb: {
197	      ...defaultConfig.database.dynamodb,
198	      workersTable: '', // No workers table for individual mode
199	      workersTableArn: '', // No workers ARN for individual mode
200	    }
201	  }
202	};
203	
204	/**
205	 * Default configuration for enterprise account type
206	 * Extends the base config with enterprise-specific settings
207	 * @type {Object}
208	 */
209	const defaultEnterpriseConfig = {
210	  ...defaultConfig,
211	  business: {
212	    ...defaultConfig.business,
213	    name: 'Empresa Multiusuário',
214	    type: 'Empresa de Serviços',
215	  }
216	};
