/* ────────────────────────────────────────────────────────────────
   api.js – SAM back-end helper with Cognito auth & mock fallback
   ----------------------------------------------------------------
   – GET /config?shop_id=…         (Cognito-protected)
   – PUT /config                   (Cognito-protected)
   – GET /appointments?shop_id=…
   – POST /appointments/book
   – GET /workers
   ---------------------------------------------------------------- */

   import {
    mockAppointments,
    mockWorkers,
    generateEmptyMockData,
  } from './mockData';

  /* ── env & helpers ────────────────────────────────────────────── */
  const API_BASE = process.env.REACT_APP_BACKEND_URL;

  const shopId = () => sessionStorage.getItem('shopId') || 'demo-shop';

  const isMockMode = () =>
    !API_BASE ||
    (API_BASE.startsWith('http://localhost') && !navigator.onLine);

  const getDatabaseConfig = () => {
    try {
      const shop = sessionStorage.getItem('shopId') || 'demo-shop';
      const storageKey = `appConfig_${shop}`;
      const cfg = JSON.parse(localStorage.getItem(storageKey) || '{}');
      return cfg.database || {};
    } catch {
      return {};
    }
  };

  /** Build headers with the JWT we stored after Hosted-UI login */
  async function authHeader() {
    const token = sessionStorage.getItem('idToken');
    return {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json',
    };
  }

  /* ────────────────────────────────────────────────────────────────
     1)  CONFIG  – GET & PUT (Cognito protected)
     ---------------------------------------------------------------- */
  export async function fetchConfig(shop = shopId()) {
    if (isMockMode()) return {};
    const headers = await authHeader();
    const r = await fetch(`${API_BASE}/config?shop_id=${shop}`, { headers });
    if (!r.ok) throw new Error(r.statusText);
    return r.json(); // {} if nothing saved yet
  }

  export async function saveConfig(cfg, shop = shopId()) {
    if (isMockMode()) return;
    const headers = await authHeader();

    // Ensure shop_id is correctly set to the current user's shop ID
    // The backend will use the shop_id from JWT claims but we set it explicitly for clarity
    const payload = { ...cfg, shop_id: shop }; // partition key for DynamoDB

    const r = await fetch(`${API_BASE}/config`, {
      method: 'PUT',
      headers,
      body: JSON.stringify(payload),
    });
    if (!r.ok) throw new Error(await r.text());
    return r.json();
  }

  /* ────────────────────────────────────────────────────────────────
     2)  APPOINTMENTS – GET
     ---------------------------------------------------------------- */
  export async function fetchAppointments(dateISO) {
    /* Offline / mock */
    if (isMockMode()) {
      return mockAppointments.filter((a) => !dateISO || a.date === dateISO);
    }

    const headers = await authHeader();
    const base = `${API_BASE}/appointments?shop_id=${shopId()}`;
    const url = dateISO ? `${base}&date=${dateISO}` : base;

    const r = await fetch(url, { headers });
    if (!r.ok) throw new Error(r.statusText);
    return (await r.json()).appointments;
  }

  /* ────────────────────────────────────────────────────────────────
     3)  WORKERS – GET
     ---------------------------------------------------------------- */
  export async function fetchWorkers() {
    const role = sessionStorage.getItem('userRole');

    /* 1) Individual tenant = single “worker” (the shop owner) */
    if (role === 'individual') {
      const ownerId   = sessionStorage.getItem('shopId');
      const ownerName = sessionStorage.getItem('workerName') || ownerId;
      return [{ worker_id: ownerId, name: ownerName }];
    }

    /* 2) Mock / offline */
    if (isMockMode()) {
      const empty = getDatabaseConfig().useEmptyData === true;
      return empty ? generateEmptyMockData().workers : mockWorkers;
    }

    /* 3) Live call */
    const headers = await authHeader();
    const res     = await fetch(`${API_BASE}/workers`, { headers });
    if (!res.ok) throw new Error(`Failed to fetch workers: ${res.statusText}`);

    const { workers = [] } = await res.json();
    return workers.map((w) => ({
      worker_id: w.worker_id,
      name: w.name || w.worker_id,
      ...w,
    }));
  }

  /* ────────────────────────────────────────────────────────────────
     4)  APPOINTMENTS – POST
     ---------------------------------------------------------------- */
  export async function bookAppointment(data) {
    if (isMockMode()) return legacyMockBook(data);

    const headers = await authHeader();
    const payload = { ...data, shop_id: shopId() };

    const r = await fetch(`${API_BASE}/appointments/book`, {
      method: 'POST',
      headers,
      body: JSON.stringify(payload),
    });
    if (!r.ok) throw new Error(await r.text());
    return r.json();
  }

  /* ────────────────────────────────────────────────────────────────
     5)  CUSTOMERS stub (later)
     ---------------------------------------------------------------- */
  export const fetchCustomers = async () => [];

  /* ────────────────────────────────────────────────────────────────
     6)  ChatGPT helper (unchanged here)
     ---------------------------------------------------------------- */
  export async function callChatApi(messages) {
    /* left as-is – your existing code goes here */
  }

  /* ────────────────────────────────────────────────────────────────
     7)  Legacy local-mock book helper
     ---------------------------------------------------------------- */
  function legacyMockBook(appt) {
    const withId = {
      ...appt,
      id:
        appt.id ||
        `${appt.date}-${appt.start_time}-${appt.worker_id}-${Date.now()}`,
    };
    mockAppointments.push(withId);
    return Promise.resolve({
      success: true,
      message: 'Appointment saved locally (mock mode)',
      id: withId.id,
    });
  }

  /* ────────────────────────────────────────────────────────────────
     8)  convenient default export
     ---------------------------------------------------------------- */
  export default {
    fetchConfig,
    saveConfig,
    fetchAppointments,
    fetchWorkers,
    fetchCustomers,
    bookAppointment,
    callChatApi,
  };

import React from 'react';
import {
  Paper,
  Typography,
  Divider,
  Grid,
  TextField,
  FormControlLabel,
  Switch,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  FormHelperText,
  Alert,
  Box
} from '@mui/material';
import { useConfig } from '../../../context/ConfigContext';

export default function IntegrationConfig() {
  const { config, updateConfig } = useConfig();

  // Handler for OpenAI integration changes
  const handleOpenAIChange = (field, value) => {
    updateConfig({
      ...config,
      openai: {
        ...(config.openai || {}),
        [field]: value
      }
    });
  };

  // Handler for chatbot settings
  const handleChatbotSettingChange = (field, value) => {
    updateConfig({
      ...config,
      chatbot: {
        ...(config.chatbot || {}),
        [field]: value
      }
    });
  };

  // Handler for WhatsApp integration changes
  const handleWhatsAppIntegrationChange = (field, value) => {
    updateConfig({
      ...config,
      messaging: {
        ...(config.messaging || {}),
        whatsappIntegration: {
          ...(config.messaging?.whatsappIntegration || {}),
          [field]: value
        }
      }
    });
  };

  // Handler for Google Calendar integration changes
  const handleCalendarIntegrationChange = (field, value) => {
    updateConfig({
      ...config,
      messaging: {
        ...(config.messaging || {}),
        googleCalendarIntegration: {
          ...(config.messaging?.googleCalendarIntegration || {}),
          [field]: value
        }
      }
    });
  };

  return (
    <Paper sx={{ p: 3, borderRadius: 2, maxHeight: 'calc(100vh - 160px)', overflow: 'auto' }}>
      <Typography variant="h5" gutterBottom>
        Integração e Sincronização
      </Typography>
      <Typography variant="body2" color="text.secondary" paragraph>
        Configure as integrações com WhatsApp, Google Calendar e OpenAI.
      </Typography>
      <Divider sx={{ my: 3 }} />

      {/* OpenAI Integration Section */}
      <Box sx={{ mb: 4 }}>
        <Typography variant="h6" gutterBottom color="primary">
          Integração OpenAI
        </Typography>
        <Grid container spacing={3}>
          <Grid item xs={12}>
            <FormControlLabel
              control={
                <Switch
                  checked={config?.openai?.enabled || false}
                  onChange={(e) => handleOpenAIChange('enabled', e.target.checked)}
                />
              }
              label="Ativar integração com OpenAI"
            />
          </Grid>
          <Grid item xs={12}>
            <TextField
              label="API Key OpenAI"
              fullWidth
              type="password"
              value={config?.openai?.apiKey || ''}
              onChange={(e) => handleOpenAIChange('apiKey', e.target.value)}
              margin="normal"
              disabled={!config?.openai?.enabled}
              helperText="Chave de API do OpenAI (https://platform.openai.com/api-keys)"
            />
          </Grid>
          <Grid item xs={12}>
            <FormControl fullWidth margin="normal">
              <InputLabel>Modelo</InputLabel>
              <Select
                value={config?.openai?.model || 'gpt-4'}
                onChange={(e) => handleOpenAIChange('model', e.target.value)}
                disabled={!config?.openai?.enabled}
                label="Modelo"
              >
                <MenuItem value="gpt-4">GPT-4</MenuItem>
                <MenuItem value="gpt-3.5-turbo">GPT-3.5 Turbo</MenuItem>
              </Select>
              <FormHelperText>Selecione o modelo do OpenAI a ser utilizado</FormHelperText>
            </FormControl>
          </Grid>
          <Grid item xs={12}>
            <Divider sx={{ my: 2 }} />
            <Typography variant="subtitle1" gutterBottom>
              Configurações do Chatbot
            </Typography>
            <FormControlLabel
              control={
                <Switch
                  checked={config?.chatbot?.guidedMode !== false}
                  onChange={(e) => handleChatbotSettingChange('guidedMode', e.target.checked)}
                />
              }
              label="Modo Guiado (fluxo estruturado passo a passo)"
            />
            <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
              No modo guiado, o chat segue um fluxo estruturado de nome → serviço → profissional → data → hora. 
              No modo livre, o usuário pode interagir com a IA de forma mais conversacional.
            </Typography>
          </Grid>
          <Grid item xs={12}>
            <Alert severity="info" sx={{ mt: 2 }}>
              <Typography variant="body2">
                A integração com o OpenAI é necessária para o funcionamento do assistente virtual. Você precisará de uma conta no OpenAI e uma chave de API válida.
              </Typography>
            </Alert>
          </Grid>
        </Grid>
      </Box>

      {/* WhatsApp Integration Section */}
      <Box sx={{ mb: 4 }}>
        <Typography variant="h6" gutterBottom color="primary">
          Integração WhatsApp
        </Typography>
        <Grid container spacing={3}>
          <Grid item xs={12}>
            <FormControlLabel
              control={
                <Switch
                  checked={config?.messaging?.whatsappIntegration?.enabled || false}
                  onChange={(e) => handleWhatsAppIntegrationChange('enabled', e.target.checked)}
                />
              }
              label="Ativar integração com WhatsApp"
            />
          </Grid>
          <Grid item xs={12} md={6}>
            <TextField
              label="Número de WhatsApp Business"
              fullWidth
              value={config?.messaging?.whatsappIntegration?.phoneNumber || ''}
              onChange={(e) => handleWhatsAppIntegrationChange('phoneNumber', e.target.value)}
              margin="normal"
              disabled={!config?.messaging?.whatsappIntegration?.enabled}
              helperText="Formato: +5511999999999"
            />
          </Grid>
          <Grid item xs={12} md={6}>
            <FormControl fullWidth margin="normal">
              <InputLabel>Provedor de API</InputLabel>
              <Select
                value={config?.messaging?.whatsappIntegration?.provider || 'twilio'}
                onChange={(e) => handleWhatsAppIntegrationChange('provider', e.target.value)}
                disabled={!config?.messaging?.whatsappIntegration?.enabled}
                label="Provedor de API"
              >
                <MenuItem value="twilio">Twilio</MenuItem>
                <MenuItem value="whatsapp-business">WhatsApp Business API</MenuItem>
              </Select>
              <FormHelperText>Selecione o provedor de integração com WhatsApp</FormHelperText>
            </FormControl>
          </Grid>
          <Grid item xs={12}>
            <TextField
              label="API Key"
              fullWidth
              type="password"
              value={config?.messaging?.whatsappIntegration?.apiKey || ''}
              onChange={(e) => handleWhatsAppIntegrationChange('apiKey', e.target.value)}
              margin="normal"
              disabled={!config?.messaging?.whatsappIntegration?.enabled}
              helperText="Chave de API do provedor selecionado"
            />
          </Grid>
        </Grid>
      </Box>

      {/* Google Calendar Integration */}
      <Box>
        <Typography variant="h6" gutterBottom color="primary">
          Integração com Google Calendar
        </Typography>
        <Grid container spacing={3}>
          <Grid item xs={12}>
            <FormControlLabel
              control={
                <Switch
                  checked={config?.messaging?.googleCalendarIntegration?.enabled || false}
                  onChange={(e) => handleCalendarIntegrationChange('enabled', e.target.checked)}
                />
              }
              label="Ativar sincronização com Google Calendar"
            />
          </Grid>
          <Grid item xs={12}>
            <TextField
              label="ID do Calendário Google"
              fullWidth
              value={config?.messaging?.googleCalendarIntegration?.calendarId || ''}
              onChange={(e) => handleCalendarIntegrationChange('calendarId', e.target.value)}
              margin="normal"
              disabled={!config?.messaging?.googleCalendarIntegration?.enabled}
              helperText="Exemplo: example@gmail.com ou o ID do calendário"
            />
          </Grid>
          <Grid item xs={12}>
            <Alert severity="info" sx={{ mt: 2 }}>
              <Typography variant="body2">
                Para conectar com o Google Calendar, você precisará autorizar o acesso usando uma conta Google. 
                As instruções detalhadas estão disponíveis na documentação de integração.
              </Typography>
            </Alert>
          </Grid>
        </Grid>
      </Box>
    </Paper>
  );
}

