  1	import React, { useState } from 'react';
  2	import {
  3	  Paper,
  4	  Typography,
  5	  Divider,
  6	  Grid,
  7	  TextField,
  8	  FormControlLabel,
  9	  Switch,
 10	  FormControl,
 11	  InputLabel,
 12	  Select,
 13	  MenuItem,
 14	  FormHelperText,
 15	  Alert,
 16	  Box,
 17	  Button,
 18	  RadioGroup,
 19	  Radio,
 20	  FormLabel,
 21	  Dialog,
 22	  DialogTitle,
 23	  DialogContent,
 24	  DialogActions,
 25	  CircularProgress
 26	} from '@mui/material';
 27	import QrCodeIcon from '@mui/icons-material/QrCode';
 28	import { useConfig } from '../../../context/ConfigContext';
 29	
 30	export default function WhatsAppConfig() {
 31	  const { config, updateConfig } = useConfig();
 32	  const [qrDialogOpen, setQrDialogOpen] = useState(false);
 33	  const [isGeneratingQR, setIsGeneratingQR] = useState(false);
 34	  const [qrCodeURL, setQrCodeURL] = useState('');
 35	  const [qrCodeError, setQrCodeError] = useState('');
 36	  
 37	  // Initialize whatsappIntegration if it doesn't exist
 38	  const whatsappConfig = config?.messaging?.whatsappIntegration || {
 39	    enabled: false,
 40	    phoneNumber: '',
 41	    provider: 'evolution-api',
 42	    apiKey: '',
 43	    filterMode: 'whitelist', // 'whitelist' or 'blacklist'
 44	    filterNumbers: [],
 45	    disableGroups: true,
 46	    adIntegration: {
 47	      enabled: false,
 48	      campaignId: ''
 49	    }
 50	  };
 51	  
 52	  // Handler for WhatsApp integration changes
 53	  const handleWhatsAppChange = (field, value) => {
 54	    const updatedWhatsApp = {
 55	      ...whatsappConfig,
 56	      [field]: value
 57	    };
 58	    
 59	    updateConfig({
 60	      ...config,
 61	      messaging: {
 62	        ...(config.messaging || {}),
 63	        whatsappIntegration: updatedWhatsApp
 64	      }
 65	    });
 66	  };
 67	  
 68	  // Handler for ad integration changes
 69	  const handleAdIntegrationChange = (field, value) => {
 70	    const updatedAdIntegration = {
 71	      ...whatsappConfig.adIntegration,
 72	      [field]: value
 73	    };
 74	    
 75	    handleWhatsAppChange('adIntegration', updatedAdIntegration);
 76	  };
 77	  
 78	  // Function to handle filter numbers input
 79	  const handleFilterNumbersChange = (e) => {
 80	    const numbersText = e.target.value;
 81	    // Split by commas, new lines, or spaces and filter out empty strings
 82	    const numbersArray = numbersText.split(/[,\n\s]+/).filter(n => n.trim());
 83	    handleWhatsAppChange('filterNumbers', numbersArray);
 84	  };
 85	  
 86	  // Generate a string representation of the filter numbers for the text field
 87	  const getFilterNumbersString = () => {
 88	    return (whatsappConfig.filterNumbers || []).join('\n');
 89	  };
 90	  
 91	  // Generate QR code for WhatsApp connection
 92	  const handleGenerateQR = async () => {
 93	    setIsGeneratingQR(true);
 94	    setQrCodeError('');
 95	    
 96	    try {
 97	      const backendUrl = process.env.REACT_APP_BACKEND_URL || 'https://example.com/api';
 98	      const shopId = whatsappConfig.phoneNumber.replace(/\D/g, ''); // Use phone number as instance ID
 99	      
100	      // Make API call to the backend to generate QR code
101	      const response = await fetch(`${backendUrl}/whatsapp/generate-qr`, {
102	        method: 'POST',
103	        headers: {
104	          'Content-Type': 'application/json',
105	          'x-api-key': process.env.REACT_APP_PUBLIC_API_KEY || ''
106	        },
107	        body: JSON.stringify({
108	          instanceId: shopId
109	        })
110	      });
111	      
112	      if (!response.ok) {
113	        throw new Error(`API responded with status ${response.status}`);
114	      }
115	      
116	      const data = await response.json();
117	      
118	      if (data.qrCodeUrl) {
119	        setQrCodeURL(data.qrCodeUrl);
120	        setQrDialogOpen(true);
121	      } else {
122	        throw new Error('QR code URL not found in response');
123	      }
