283	      const shop = sessionStorage.getItem('shopId');
284	      const storageKey = getConfigStorageKey(shop);
285	      
286	      // First try to load from shop-specific storage key
287	      try {
288	        const saved = localStorage.getItem(storageKey);
289	        if (saved) {
