291	        }
292	      } catch (error) {
293	        console.error(`Error reading config from ${storageKey}:`, error);
294	      }
295	  
296	      // If no shop-specific config found, check for legacy 'appConfig' key
297	      try {
298	        const legacyConfig = localStorage.getItem('appConfig');
299	        if (legacyConfig && shop) {
300	          // Migrate legacy config to shop-specific storage
301	          localStorage.setItem(storageKey, legacyConfig);
302	          localStorage.removeItem('appConfig'); // Clean up legacy key
303	          console.log(`Migrated legacy config to ${storageKey}`);
304	          return JSON.parse(legacyConfig);
305	        }
306	      } catch (error) {
307	        console.error('Error migrating legacy config:', error);
308	      }
