310	      // Fallback based on role
311	      const role = sessionStorage.getItem('userRole');
312	      if (role === 'enterprise') return defaultEnterpriseConfig;
313	      if (role === 'individual') return defaultIndividualConfig;
314	      return defaultConfig;
315	    } catch (error) {
316	      console.error('Error initializing config, falling back to default', error);
317	      return defaultConfig;
318	    }
