    });
  };

  // Handler for nested input change (for arrays or objects)
  const handleNestedInputChange = (section, index, field, value) => {
    const updatedSection = [...currentConfig[section]];
    updatedSection[index] = {
      ...updatedSection[index],
      [field]: value
