  1	/* ────────────────────────────────────────────────────────────────
  2	   api.js – SAM back-end helper with Cognito auth & mock fallback
  3	   ----------------------------------------------------------------
  4	   – GET /config?shop_id=…         (Cognito-protected)
  5	   – PUT /config                   (Cognito-protected)
  6	   – GET /appointments?shop_id=…
  7	   – POST /appointments/book
  8	   – GET /workers
  9	   ---------------------------------------------------------------- */
 10	
 11	   import {
 12	    mockAppointments,
 13	    mockWorkers,
 14	    generateEmptyMockData,
 15	  } from './mockData';
 16	  
 17	  /* ── env & helpers ────────────────────────────────────────────── */
 18	  const API_BASE = process.env.REACT_APP_BACKEND_URL;
 19	  
 20	  const shopId = () => sessionStorage.getItem('shopId') || 'demo-shop';
 21	  
 22	  const isMockMode = () =>
 23	    !API_BASE ||
 24	    (API_BASE.startsWith('http://localhost') && !navigator.onLine);
 25	  
 26	  const getDatabaseConfig = () => {
 27	    try {
 28	      const shop = sessionStorage.getItem('shopId') || 'demo-shop';
 29	      const storageKey = `appConfig_${shop}`;
 30	      const cfg = JSON.parse(localStorage.getItem(storageKey) || '{}');
 31	      return cfg.database || {};
 32	    } catch {
 33	      return {};
 34	    }
 35	  };
 36	  
 37	  /** Build headers with the JWT we stored after Hosted-UI login */
 38	  async function authHeader() {
 39	    const token = sessionStorage.getItem('idToken');
 40	    return {
 41	      Authorization: `Bearer ${token}`,
 42	      'Content-Type': 'application/json',
 43	    };
 44	  }
 45	  
 46	  /* ────────────────────────────────────────────────────────────────
 47	     1)  CONFIG  – GET & PUT (Cognito protected)
 48	     ---------------------------------------------------------------- */
 49	  export async function fetchConfig(shop = shopId()) {
 50	    if (isMockMode()) return {};
 51	    try {
 52	      const headers = await authHeader();
 53	      const r = await fetch(`${API_BASE}/config?shop_id=${shop}`, { headers });
 54	      if (!r.ok) throw new Error(await r.text());
 55	      return r.json(); // {} if nothing saved yet
 56	    } catch (error) {
 57	      console.error('Error fetching config:', error);
 58	      throw error;
 59	    }
 60	  }
 61	  
 62	  export async function saveConfig(cfg, shop = shopId()) {
 63	    if (isMockMode()) return;
 64	    try {
 65	      const headers = await authHeader();
 66	      
 67	      // Ensure shop_id is correctly set to the current user's shop ID
 68	      // The backend will use the shop_id from JWT claims but we set it explicitly for clarity
 69	      const payload = { ...cfg, shop_id: shop }; // partition key for DynamoDB
 70	      
 71	      const r = await fetch(`${API_BASE}/config`, {
 72	        method: 'PUT',
 73	        headers,
 74	        body: JSON.stringify(payload),
 75	      });
 76	      if (!r.ok) throw new Error(await r.text());
 77	      return r.json();
 78	    } catch (error) {
 79	      console.error('Error saving config:', error);
 80	      throw error;
 81	    }
 82	  }
 83	  
 84	  /* ────────────────────────────────────────────────────────────────
 85	     2)  APPOINTMENTS – GET
 86	     ---------------------------------------------------------------- */
 87	  export async function fetchAppointments(dateISO) {
 88	    /* Offline / mock */
 89	    if (isMockMode()) {
 90	      return mockAppointments.filter((a) => !dateISO || a.date === dateISO);
 91	    }
 92	  
 93	    const headers = await authHeader();
 94	    const base = `${API_BASE}/appointments?shop_id=${shopId()}`;
 95	    const url = dateISO ? `${base}&date=${dateISO}` : base;
 96	  
 97	    const r = await fetch(url, { headers });
 98	    if (!r.ok) throw new Error(r.statusText);
 99	    return (await r.json()).appointments;
100	  }
101	  
102	  /* ────────────────────────────────────────────────────────────────
103	     3)  WORKERS – GET
104	     ---------------------------------------------------------------- */
105	  export async function fetchWorkers() {
106	    const role = sessionStorage.getItem('userRole');
107	  
108	    /* 1) Individual tenant = single “worker” (the shop owner) */
109	    if (role === 'individual') {
110	      const ownerId   = sessionStorage.getItem('shopId');
111	      const ownerName = sessionStorage.getItem('workerName') || ownerId;
112	      return [{ worker_id: ownerId, name: ownerName }];
113	    }
114	  
115	    /* 2) Mock / offline */
116	    if (isMockMode()) {
117	      const empty = getDatabaseConfig().useEmptyData === true;
118	      return empty ? generateEmptyMockData().workers : mockWorkers;
119	    }
120	  
121	    /* 3) Live call */
122	    const headers = await authHeader();
123	    const res     = await fetch(`${API_BASE}/workers`, { headers });
124	    if (!res.ok) throw new Error(`Failed to fetch workers: ${res.statusText}`);
125	  
126	    const { workers = [] } = await res.json();
127	    return workers.map((w) => ({
128	      worker_id: w.worker_id,
129	      name: w.name || w.worker_id,
130	      ...w,
131	    }));
132	  }
133	  
134	  /* ────────────────────────────────────────────────────────────────
135	     4)  APPOINTMENTS – POST
136	     ---------------------------------------------------------------- */
137	  export async function bookAppointment(data) {
138	    if (isMockMode()) return legacyMockBook(data);
139	  
140	    const headers = await authHeader();
141	    const payload = { ...data, shop_id: shopId() };
142	  
143	    const r = await fetch(`${API_BASE}/appointments/book`, {
144	      method: 'POST',
145	      headers,
146	      body: JSON.stringify(payload),
147	    });
148	    if (!r.ok) throw new Error(await r.text());
149	    return r.json();
150	  }
151	  
152	  /* ────────────────────────────────────────────────────────────────
153	     5)  CUSTOMERS API
154	     ---------------------------------------------------------------- */
155	  export async function fetchCustomers() {
156	    if (isMockMode()) {
157	      return []; // TODO: Add mock customer data when needed
158	    }
159	
160	    try {
161	      const headers = await authHeader();
162	      const r = await fetch(`${API_BASE}/customers?shop_id=${shopId()}`, { headers });
163	      
164	      if (!r.ok) throw new Error(await r.text());
165	      const data = await r.json();
166	      return data.customers || [];
167	    } catch (error) {
168	      console.error('Error fetching customers:', error);
169	      // Return empty array instead of throwing to avoid breaking UI
170	      return [];
171	    }
172	  }
173	  
174	  /* ────────────────────────────────────────────────────────────────
175	     6)  ChatGPT helper
176	     ---------------------------------------------------------------- */
177	  export async function callChatApi(messages) {
178	    if (isMockMode()) {
179	      return Promise.resolve({
180	        response: "This is a mock response. Please configure the OpenAI API to use the chat feature.",
181	        success: true
182	      });
183	    }
184	
185	    try {
186	      // Get config from localStorage
187	      const shop = sessionStorage.getItem('shopId') || 'demo-shop';
188	      const storageKey = `appConfig_${shop}`;
189	      const cfg = JSON.parse(localStorage.getItem(storageKey) || '{}');
190	      
191	      // Check if OpenAI is enabled and API key exists
192	      if (!cfg.openai?.enabled || !cfg.openai?.apiKey) {
193	        throw new Error('OpenAI is not enabled or API key is missing');
194	      }
195	      
196	      const headers = await authHeader();
197	      
198	      // Use backend proxy instead of direct OpenAI call for security
199	      const response = await fetch(`${API_BASE}/chat`, {
200	        method: 'POST',
201	        headers,
202	        body: JSON.stringify({ 
203	          messages,
204	          shop_id: shopId()
205	        }),
206	      });
207	      
208	      if (!response.ok) {
209	        throw new Error(await response.text());
210	      }
211	      
212	      return await response.json();
213	    } catch (error) {
214	      console.error('Error calling chat API:', error);
215	      return {
216	        error: error.message,
217	        success: false
218	      };
219	    }
220	  }
